pub struct InsertSignalParams {
    pub r#id: String,
    pub r#task_id: String,
    pub r#signal_name: String,
    pub r#signal_key: String,
    pub r#payload_json: String,
    pub r#created_at_ms: i64,
}

pub type InsertSignalRow = TaskSignalsRow;

pub async fn r#insert_signal<'e>(
    db: impl sqlx::SqliteExecutor<'e>,
    params: InsertSignalParams,
) -> Result<InsertSignalRow, sqlx::Error> {
    sqlx::query_as::<_, InsertSignalRow>(r#"INSERT INTO durable_signal(id,task_id,signal_name,signal_key,payload_json,insert_seq,created_at_ms) VALUES (?1,?2,?3,?4,?5,(SELECT COALESCE(MAX(insert_seq),0)+1 FROM durable_signal),?6) RETURNING id, task_id, signal_name, signal_key, payload_json, consumed, consumed_at_ms, created_at_ms"#)
        .bind(params.r#id)
        .bind(params.r#task_id)
        .bind(params.r#signal_name)
        .bind(params.r#signal_key)
        .bind(params.r#payload_json)
        .bind(params.r#created_at_ms)
        .fetch_one(db).await
}

pub struct ConsumeSignalParams {
    pub r#consumed_at_ms: i64,
    pub r#task_id: String,
    pub r#signal_name: String,
}

pub type ConsumeSignalRow = TaskSignalsRow;

pub async fn r#consume_signal<'e>(
    db: impl sqlx::SqliteExecutor<'e>,
    params: ConsumeSignalParams,
) -> Result<ConsumeSignalRow, sqlx::Error> {
    sqlx::query_as::<_, ConsumeSignalRow>(r#"UPDATE durable_signal SET consumed=1,consumed_at_ms=?1 WHERE id=(SELECT next.id FROM durable_signal AS next WHERE next.task_id=?2 AND next.signal_name=?3 AND next.consumed=0 ORDER BY next.insert_seq LIMIT 1) RETURNING id, task_id, signal_name, signal_key, payload_json, consumed, consumed_at_ms, created_at_ms"#)
        .bind(params.r#consumed_at_ms)
        .bind(params.r#task_id)
        .bind(params.r#signal_name)
        .fetch_one(db).await
}
